import java.util.List;

public class Main {

    enum Prop { REQUIRED, REQUIRES_NEW, NESTED, SUPPORTS, NOT_SUPPORTED, MANDATORY, NEVER }

    static class Tx {
        final int id;
        final java.util.List<String> ops = new java.util.ArrayList<>();
        final java.util.List<Integer> savepoints = new java.util.ArrayList<>();
        Tx(int id) { this.id = id; }
    }

    static class TxManager {
        final java.util.List<String> db = new java.util.ArrayList<>();
        int seq = 0;
        Tx current = null;

        Tx begin(Prop p) {
            switch (p) {
                case REQUIRED:
                    if (current != null) return current;
                    current = new Tx(++seq);
                    return current;
                case REQUIRES_NEW: {
                    current = new Tx(++seq);
                    return current;
                }
                case NESTED:
                    if (current != null) {
                        current.savepoints.add(current.ops.size());
                        System.out.println("savepoint sp" + current.savepoints.size()
                                + " at depth " + current.ops.size());
                        return current;
                    }
                    current = new Tx(++seq);
                    return current;
                case SUPPORTS:
                    return current;
                case NOT_SUPPORTED:
                    current = null;
                    return null;
                case MANDATORY:
                    if (current == null)
                        throw new IllegalStateException("No existing transaction found for MANDATORY");
                    return current;
                case NEVER:
                    if (current != null)
                        throw new IllegalStateException("Existing transaction found for NEVER");
                    return null;
                default:
                    return current;
            }
        }

        void op(String s) {
            if (current != null) current.ops.add(s);
            else db.add(s);
        }

        void commit(Tx t) {
            if (t == null) return;
            db.addAll(t.ops);
            if (current == t) current = null;
        }

        void rollback(Tx t) {
            if (current == t) current = null;
        }

        void rollbackToSavepoint(Tx t) {
            if (t == null || t.savepoints.isEmpty()) return;
            int mark = t.savepoints.remove(t.savepoints.size() - 1);
            while (t.ops.size() > mark) t.ops.remove(t.ops.size() - 1);
        }
    }

    public static void main(String[] args) {
        TxManager tm = new TxManager();

        Tx outer = tm.begin(Prop.REQUIRED);
        Tx s1 = tm.begin(Prop.SUPPORTS);
        System.out.println("SUPPORTS joins existing tx: " + (s1 == outer));

        tm.current = null;
        Tx s2 = tm.begin(Prop.SUPPORTS);
        tm.op("insert:direct");
        System.out.println("SUPPORTS without tx runs non-transactionally, auto-committed: "
                + (s2 == null && tm.db.contains("insert:direct")));

        boolean mandatoryThrows = false;
        try { tm.begin(Prop.MANDATORY); }
        catch (IllegalStateException e) { mandatoryThrows = true; }
        System.out.println("MANDATORY without tx throws: " + mandatoryThrows);

        tm.current = tm.begin(Prop.REQUIRED);
        boolean neverThrows = false;
        try { tm.begin(Prop.NEVER); }
        catch (IllegalStateException e) { neverThrows = true; }
        System.out.println("NEVER with active tx throws: " + neverThrows);

        tm.begin(Prop.REQUIRED);
        Tx n = tm.begin(Prop.NOT_SUPPORTED);
        tm.op("insert:notx");
        System.out.println("NOT_SUPPORTED suspends outer tx, write auto-committed: "
                + (n == null && tm.db.contains("insert:notx")));
        System.out.println("db=" + tm.db);
    }
}
